def check_snapshot(base):
    snap=json.loads((base/'snapshot.json').read_text())
    observed={p:digest((base/p).read_bytes()) for p in snap['files']}
    canonical=digest(json.dumps(snap['files'],sort_keys=True,separators=(',',':')).encode())
    return {'files_checked':len(observed),'mismatches':[p for p in observed if observed[p]!=snap['files'][p]],
            'digest':snap['digest'],'canonical_digest_matches':canonical==snap['digest'],'observed':observed}
